files.game.js:
const config = {
  type: Phaser.AUTO,
  width: 600,
  height: 700,
  backgroundColor: '#16213e',
  scene: { preload, create, update }
};

const gridSize = 8;
const gemSize = 60;
const gemTypes = 5;
let grid = [];
let selectedGem = null;
let score = 0, moves = 30;
let scoreText, movesText;
let canSelect = true;

const game = new Phaser.Game(config);

function preload() {
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });

  // Create colored gems
  const colors = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff];
  colors.forEach((color, i) => {
    graphics.clear();
    graphics.fillStyle(color, 1);
    graphics.fillCircle(gemSize / 2, gemSize / 2, gemSize / 2 - 5);
    graphics.lineStyle(3, 0xffffff, 1);
    graphics.strokeCircle(gemSize / 2, gemSize / 2, gemSize / 2 - 5);
    graphics.generateTexture('gem' + i, gemSize, gemSize);
  });
}

function create() {
  // Title
  this.add.text(300, 30, 'Match-3 Puzzle', {
    fontSize: '32px',
    fill: '#fff'
  }).setOrigin(0.5);

  // Score and moves
  scoreText = this.add.text(50, 620, 'Score: 0', {
    fontSize: '24px',
    fill: '#fff'
  });
  movesText = this.add.text(400, 620, 'Moves: 30', {
    fontSize: '24px',
    fill: '#fff'
  });

  // Initialize grid
  for (let row = 0; row < gridSize; row++) {
    grid[row] = [];
    for (let col = 0; col < gridSize; col++) {
      createGem.call(this, row, col);
    }
  }

  // Remove initial matches
  while (checkMatches.call(this)) {
    removeMatches.call(this);
    dropGems.call(this);
  }
}

function update() {}

function createGem(row, col) {
  const x = 75 + col * gemSize;
  const y = 100 + row * gemSize;
  const type = Phaser.Math.Between(0, gemTypes - 1);
  const gem = this.add.sprite(x, y, 'gem' + type);
  gem.setInteractive();
  gem.row = row;
  gem.col = col;
  gem.gemType = type;

  gem.on('pointerdown', () => selectGem.call(this, gem));

  grid[row][col] = gem;
  return gem;
}

function selectGem(gem) {
  if (!canSelect || moves <= 0) return;

  if (!selectedGem) {
    selectedGem = gem;
    gem.setScale(1.2);
  } else {
    // Check if gems are adjacent
    const rowDiff = Math.abs(selectedGem.row - gem.row);
    const colDiff = Math.abs(selectedGem.col - gem.col);

    if ((rowDiff === 1 && colDiff === 0) || (rowDiff === 0 && colDiff === 1)) {
      swapGems.call(this, selectedGem, gem);
    }

    selectedGem.setScale(1);
    selectedGem = null;
  }
}

function swapGems(gem1, gem2) {
  canSelect = false;

  // Swap in grid
  grid[gem1.row][gem1.col] = gem2;
  grid[gem2.row][gem2.col] = gem1;

  const tempRow = gem1.row;
  const tempCol = gem1.col;
  gem1.row = gem2.row;
  gem1.col = gem2.col;
  gem2.row = tempRow;
  gem2.col = tempCol;

  // Animate swap
  this.tweens.add({
    targets: gem1,
    x: 75 + gem1.col * gemSize,
    y: 100 + gem1.row * gemSize,
    duration: 200
  });

  this.tweens.add({
    targets: gem2,
    x: 75 + gem2.col * gemSize,
    y: 100 + gem2.row * gemSize,
    duration: 200,
    onComplete: () => {
      if (checkMatches.call(this)) {
        moves--;
        movesText.setText('Moves: ' + moves);
        processMatches.call(this);
      } else {
        // Swap back
        swapGems.call(this, gem1, gem2);
        canSelect = true;
      }

      if (moves <= 0) {
        this.add.text(300, 350, 'Game Over!\nScore: ' + score, {
          fontSize: '48px',
          fill: '#fff',
          align: 'center'
        }).setOrigin(0.5);
      }
    }
  });
}

function checkMatches() {
  let hasMatch = false;

  // Check horizontal
  for (let row = 0; row < gridSize; row++) {
    for (let col = 0; col < gridSize - 2; col++) {
      const gem = grid[row][col];
      if (gem && grid[row][col + 1] && grid[row][col + 2] &&
          gem.gemType === grid[row][col + 1].gemType &&
          gem.gemType === grid[row][col + 2].gemType) {
        gem.matched = true;
        grid[row][col + 1].matched = true;
        grid[row][col + 2].matched = true;
        hasMatch = true;
      }
    }
  }

  // Check vertical
  for (let col = 0; col < gridSize; col++) {
    for (let row = 0; row < gridSize - 2; row++) {
      const gem = grid[row][col];
      if (gem && grid[row + 1][col] && grid[row + 2][col] &&
          gem.gemType === grid[row + 1][col].gemType &&
          gem.gemType === grid[row + 2][col].gemType) {
        gem.matched = true;
        grid[row + 1][col].matched = true;
        grid[row + 2][col].matched = true;
        hasMatch = true;
      }
    }
  }

  return hasMatch;
}

function removeMatches() {
  for (let row = 0; row < gridSize; row++) {
    for (let col = 0; col < gridSize; col++) {
      const gem = grid[row][col];
      if (gem && gem.matched) {
        score += 10;
        gem.destroy();
        grid[row][col] = null;
      }
    }
  }
  scoreText.setText('Score: ' + score);
}

function dropGems() {
  for (let col = 0; col < gridSize; col++) {
    let emptySpaces = 0;
    for (let row = gridSize - 1; row >= 0; row--) {
      if (!grid[row][col]) {
        emptySpaces++;
      } else if (emptySpaces > 0) {
        const gem = grid[row][col];
        grid[row + emptySpaces][col] = gem;
        grid[row][col] = null;
        gem.row = row + emptySpaces;

        this.tweens.add({
          targets: gem,
          y: 100 + gem.row * gemSize,
          duration: 300
        });
      }
    }

    // Fill empty spaces at top
    for (let row = 0; row < emptySpaces; row++) {
      createGem.call(this, row, col);
    }
  }
}

function processMatches() {
  removeMatches.call(this);
  dropGems.call(this);

  this.time.delayedCall(400, () => {
    if (checkMatches.call(this)) {
      processMatches.call(this);
    } else {
      canSelect = true;
    }
  });
}
